package com.taylordproductivty.med_timing_tracker.data

import androidx.room.Dao
import androidx.room.Insert
import androidx.room.Query
import androidx.room.Update
import kotlinx.coroutines.flow.Flow

@Dao
interface ProfileDao {
    @Query("SELECT * FROM profiles WHERE isArchived = 0 ORDER BY name ASC")
    fun observeActive(): Flow<List<Profile>>

    // Snapshot read for callers outside the UI (notification receivers, widget) that
    // can't collect a Flow.
    @Query("SELECT * FROM profiles WHERE isArchived = 0 ORDER BY name ASC")
    suspend fun getActiveSnapshot(): List<Profile>

    @Query("SELECT * FROM profiles WHERE id = :id")
    suspend fun getById(id: Int): Profile?

    @Insert
    suspend fun insert(profile: Profile): Long

    @Update
    suspend fun update(profile: Profile)
}
